namespace {
struct Record {std::string operation;Json before,after,functionBefore,functionAfter,sectionBefore,sectionAfter;size_t bytes=0;};
struct History {std::deque<Record> undo,redo;size_t bytes=0,dropped=0;};
constexpr size_t byteLimit=32*1024*1024,recordLimit=128;
History& history(Engine&e){auto&slot=e.runtimeSlots()["edit_history"];if(!slot)slot=std::make_shared<History>();return *std::static_pointer_cast<History>(slot);}
Json metadata(Engine&e){auto j=e.workspaceState();if(j.contains("advanced"))j["advanced"].erase("analysis");return j;}
Json functionRow(const Function&f){return {{"address",hex(f.va)},{"end",hex(f.end)},{"name",f.name},{"source",f.source}};}
std::pair<Json,Json> functionDiff(const std::vector<Function>&before,const std::vector<Function>&after){Json a=Json::array(),b=Json::array();size_t i=0,j=0;while(i<before.size()||j<after.size()){if(j==after.size()||(i<before.size()&&before[i].va<after[j].va)){a.push_back(functionRow(before[i]));b.push_back({{"address",hex(before[i++].va)},{"deleted",true}});}else if(i==before.size()||after[j].va<before[i].va){a.push_back({{"address",hex(after[j].va)},{"deleted",true}});b.push_back(functionRow(after[j++]));}else{auto old=functionRow(before[i++]),now=functionRow(after[j++]);if(old!=now){a.push_back(std::move(old));b.push_back(std::move(now));}}}return {a,b};}
Json sectionRows(const std::vector<Section>&sections){Json rows=Json::array();for(auto&s:sections)rows.push_back({{"name",s.name},{"va",hex(s.va)},{"memorySize",s.memorySize},{"offset",s.offset},{"fileSize",s.fileSize},{"executable",s.executable},{"writable",s.writable}});return rows;}
void apply(Engine&e,const Json&workspace,const Json&functions,const Json&sections){auto*binary=e.editableBinary();if(!binary)throw std::runtime_error("Open a binary first");auto updated=binary->functions;for(auto&row:functions){auto va=address(row.at("address"));auto found=std::lower_bound(updated.begin(),updated.end(),va,[](const Function&f,Address a){return f.va<a;});if(row.value("deleted",false)){if(found!=updated.end()&&found->va==va)updated.erase(found);}else{Function f{va,address(row.at("end")),row.at("name"),row.at("source")};if(found!=updated.end()&&found->va==va)*found=std::move(f);else updated.insert(found,std::move(f));}}
 auto oldFunctions=binary->functions;auto oldSections=binary->sections;auto oldWorkspace=metadata(e);try{binary->functions=std::move(updated);if(!sections.is_null()){if(sections.size()!=binary->sections.size())throw std::runtime_error("Section undo mismatch");for(size_t i=0;i<sections.size();++i){auto&r=sections[i];auto&s=binary->sections[i];if(address(r.at("va"))!=s.va||r.at("memorySize")!=s.memorySize||r.at("offset")!=s.offset||r.at("fileSize")!=s.fileSize)throw std::runtime_error("Section undo mapping mismatch");s.name=r.at("name");s.executable=r.at("executable");s.writable=r.at("writable");}}e.rebuildArchitecture();e.restoreWorkspaceState(workspace);}catch(...){binary->functions=std::move(oldFunctions);binary->sections=std::move(oldSections);e.rebuildArchitecture();e.restoreWorkspaceState(oldWorkspace);throw;}}
bool tracked(const std::string&n){static const std::set<std::string> names={"rename_function","set_comment","set_bookmark","remove_bookmark","set_label","set_function_signature","set_variable_type","stage_patch","remove_patch","define_code","define_data","create_function","delete_function","set_function_bounds","split_function","merge_functions","set_operand_presentation","define_switch_table","edit_segment","define_type","delete_type","import_c_header","load_type_library","load_debug_symbols","rename_variable","set_call_site_signature","set_indirect_call_target","force_pseudocode_goto","mark_multistage_jump","set_pseudocode_options","reset_pseudocode_controls","clear_definition","clear_operand_presentation","remove_switch_table"};return names.contains(n);}
bool functionsChange(const std::string&n){return n=="rename_function"||n=="set_function_signature"||n=="load_debug_symbols"||n.find("function")!=std::string::npos;}
}
EditHistoryGuard::EditHistoryGuard(Engine&e,const std::string&n):engine_(e),operation_(n),exceptions_(std::uncaught_exceptions()){if(!e.binary()||!tracked(n))return;before_=metadata(e);if(functionsChange(n))functions_=e.binary()->functions;if(n=="edit_segment")sections_=e.binary()->sections;active_=true;}
EditHistoryGuard::~EditHistoryGuard(){if(!active_||std::uncaught_exceptions()!=exceptions_)return;try{auto after=metadata(engine_);Json a=Json::array(),b=Json::array();if(functionsChange(operation_))std::tie(a,b)=functionDiff(functions_,engine_.binary()->functions);Json sa,sb;if(!sections_.empty()){sa=sectionRows(sections_);sb=sectionRows(engine_.binary()->sections);if(sa==sb)sa=sb=nullptr;}if(before_==after&&a.empty()&&sa.is_null())return;auto&h=history(engine_);for(auto&r:h.redo)h.bytes-=r.bytes;h.redo.clear();Record r{operation_,std::move(before_),std::move(after),std::move(a),std::move(b),std::move(sa),std::move(sb)};r.bytes=r.before.dump().size()+r.after.dump().size()+r.functionBefore.dump().size()+r.functionAfter.dump().size()+r.sectionBefore.dump().size()+r.sectionAfter.dump().size();if(r.bytes>byteLimit){h.undo.clear();h.bytes=0;++h.dropped;return;}while(!h.undo.empty()&&(h.undo.size()>=recordLimit||h.bytes+r.bytes>byteLimit)){h.bytes-=h.undo.front().bytes;h.undo.pop_front();++h.dropped;}h.bytes+=r.bytes;h.undo.push_back(std::move(r));notifySdkEvent(engine_,"workspace_edited",{{"operation",operation_}});}catch(...){} }
Json databaseTools(){Json rows=Json::array();auto add=[&](const char*n,const char*d,Json props,Json required,bool read){rows.push_back({{"name",n},{"description",d},{"inputSchema",{{"type","object"},{"properties",props},{"required",required},{"additionalProperties",false}}},{"annotations",{{"readOnlyHint",read},{"destructiveHint",false},{"openWorldHint",false}}}});};Json path={{"type","string"},{"minLength",1},{"maxLength",32768}};add("save_analysis_database","Save the project and bounded decoded, graph, reference and pseudocode caches atomically.",{{"path",path}},{"path"},false);add("load_analysis_database","Verify binary identity and restore persistent analysis and edits.",{{"path",path}},{"path"},false);add("get_analysis_cache_stats","Inspect retained analysis cache and undo history sizes.",Json::object(),Json::array(),true);add("clear_analysis_cache","Discard derived caches while preserving analysis edits.",Json::object(),Json::array(),false);add("undo","Undo the latest retained analysis edit.",Json::object(),Json::array(),false);add("redo","Reapply an undone analysis edit.",Json::object(),Json::array(),false);add("get_undo_history","List bounded undo/redo operations and dropped history count.",Json::object(),Json::array(),true);return rows;}
std::optional<Json> callDatabaseTool(Engine&e,const std::string&n,const Json&a){if(n=="save_analysis_database")return e.saveProject(std::filesystem::u8path(a.at("path").get<std::string>()));if(n=="load_analysis_database")return e.loadProject(std::filesystem::u8path(a.at("path").get<std::string>()));if(n=="clear_analysis_cache"){e.invalidateDecompilation();e.advancedState().erase("analysis");size_t native=0;for(auto it=e.runtimeSlots().begin();it!=e.runtimeSlots().end();)if((it->first.starts_with("auto.")||it->first.starts_with("auto_"))&&it->first!="auto_import_semantics"){it=e.runtimeSlots().erase(it);++native;}else ++it;return Json{{"cleared",true},{"native_detail_caches_removed",native}};}if(n=="get_analysis_cache_stats"){auto j=e.analysisState();auto&h=history(e);size_t native=0;for(const auto&slot:e.runtimeSlots())if((slot.first.starts_with("auto.")||slot.first.starts_with("auto_"))&&slot.first!="auto_import_semantics")++native;return Json{{"pseudocode_functions",j["pseudocode"].size()},{"decoded_pages",j["decoded"].size()},{"graphs",j["graphs"].size()},{"cache_bytes",j.dump().size()},{"undo_bytes",h.bytes},{"undo_limit_bytes",byteLimit},{"undo_limit_records",recordLimit},{"native_detail_caches",native},{"native_detail_persistence","session only"},{"cache_persistence","project-v3 bounded legacy caches and auto summaries"}};}if(n=="get_undo_history"){auto&h=history(e);Json undo=Json::array(),redo=Json::array();for(auto&r:h.undo)undo.push_back(r.operation);for(auto&r:h.redo)redo.push_back(r.operation);return Json{{"undo",undo},{"redo",redo},{"retained_bytes",h.bytes},{"dropped",h.dropped},{"persisted",false}};}if(n=="undo"||n=="redo"){auto&h=history(e);auto&source=n=="undo"?h.undo:h.redo;auto&destination=n=="undo"?h.redo:h.undo;if(source.empty())throw std::runtime_error("No edit available to "+n);auto&r=source.back();apply(e,n=="undo"?r.before:r.after,n=="undo"?r.functionBefore:r.functionAfter,n=="undo"?r.sectionBefore:r.sectionAfter);auto operation=r.operation;destination.push_back(std::move(r));source.pop_back();return Json{{"operation",operation},{"action",n},{"undo_count",h.undo.size()},{"redo_count",h.redo.size()}};}return std::nullopt;}
